PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE src_meta (
  kind        TEXT    NOT NULL,
  id          INTEGER NOT NULL,       -- 生物、任務、物件編號
  name        TEXT,                   -- NPC 名字；任務是任務名稱
  giver       TEXT,                   -- 任務：給任務的（n生物編號／o物件編號）
  giver_name  TEXT,
  turnin      TEXT,                   -- 任務：交給誰
  turnin_name TEXT,
  updated     INTEGER NOT NULL,
  PRIMARY KEY (kind, id)
);
